          "correctKey": "Г",
          "answerText": "Державотворче піднесення змінилося катастрофою: Україну знову підкорила імперська влада в комуністичній формі. На цьому тлі від’їзд 1919 року представлено як вимушений. Відень став першим місцем перебування, Прага — тривалим осередком еміграційного життя.",
