          "correctKey": "А",
          "answerText": "Псевдонім має особисте джерело: так наречена зверталася до майбутнього автора під час подорожі 1906 року. Коли наступного року вийшла дебютна збірка, це ім’я з’явилося на її обкладинці й стало літературним підписом поета.",
