          "answerText": "Почуття закоханої людини й весняне довкілля в романсі постають разом. Рух води, пташиний спів і нічне пробудження природи підтримують заклик цінувати коротку мить молодості. Так утворюється єдність любовної та пейзажної лірики.",
          "optionSource": "prepared-v21-test",
