          "answerText": "Заклик героя пов’язаний із усвідомленням часу: життя не можна повернути назад. Тому він спрямовує людину до активного переживання краси, любові й молодості. Точного віку ця настанова не визначає; індивідуальний учнівський портрет має залишатися сумісним із текстом.",
