          "answerText": "Кожна строфа моделює можливість: співпереживання могло б перейти в силу віри, а гнів — у спротив. Умовність загострює різницю між потенціалом народу та байдужим станом, який поет прагне подолати. Три емоційні ступені підтримують заклик до пробудження.",
