          "correctKey": "В",
          "answerText": "Символи надають емоційному закликові суспільного виміру. Вони говорять про тягар, підкорення й силу майбутнього спротиву. Поряд із цим образ незрячих позначає духовну нечутливість, а кат — уособлення гноблення; весь ряд підтримує тему виходу з байдужості.",
