          "correctKey": "В",
          "answerText": "Три строфи послідовно переводять колективне переживання від співчуття до внутрішньої опори й далі до активної реакції. Цей рух прямо пояснений у параграфі. Тест охоплює композиційний рядок паспорта, тоді як жанр, образи, засоби й віршова організація мають бути заповнені окремо.",
          "optionSource": "prepared-v21-test",
