          "answerText": "Джерела болю мають і зовнішній, і внутрішній вимір. Тиск середовища позбавляє свободи та гідності; страх і відступ від дії не дозволяють подолати цей тиск. Оксана гостро переживає втрату рідного краю, Степан — залежність від царської служби й нагляду.",
