          "answerText": "До переїзду героїня сподівається, що поруч із коханим не буде чужини. Реальний побут спростовує ці очікування: обмеження, страх і відрив від Батьківщини стають джерелом духовної неволі. Водночас почуття до чоловіка не зникає, тому конфлікт особливо болісний.",
