          "type": "single",
          "topic": "§14-15. Мотиви та пафос лірики Володимира Сосюри",
          "questionHtml": "<p>Який смисловий рух утворює алегорія саду від початку до фіналу?</p>",
          "options": [
            {
              "key": "А",
              "text": "Від понівечення рідного краю й виснаження до пробудження та відновлення життя."
            },
            {
              "key": "Б",
              "text": "Від байдужої прикраси довкілля до суто ботанічної класифікації рослин."
            },
            {
              "key": "В",
              "text": "Від незмінного добробуту до такого самого добробуту без будь-якого конфлікту."
            },
            {
              "key": "Г",
              "text": "Від повного відродження на початку до остаточної й безнадійної загибелі у фіналі."
            }
          ],
          "correctKey": "А",
          "answerText": "Фінальне ототожнення саду з Батьківщиною пояснює алегорію всього твору. Початкове нищення залишає пеньки й бур’яни, але новий спів змінює людей і природу: життя проростає знову. Образ крука додає трагічної тривоги й водночас голосу спротиву.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
