          "correctKey": "А",
          "answerText": "Приклади показують силу почуття, образне піднесення й прагнення подолати буденний або поневолений стан. У параграфі ці якості конкретизовано як неоромантичні. Тому відповідь має бути аргументована творами, а не перенесена механічно на все, що коли-небудь написав поет.",
          "optionSource": "prepared-v21-test",
