          "sourceCardId": "32-33.06",
          "type": "single",
          "topic": "§32-33. Поезія з війни",
          "questionHtml": "<p>Хто є автором циклу «Марсове поле», наведеного в підручнику?</p>",
          "options": [
            {
              "key": "А",
              "text": "Володимир Сосюра."
            },
            {
              "key": "Б",
              "text": "Артур Дронь."
            },
            {
              "key": "В",
              "text": "Олександр Олесь."
            },
            {
              "key": "Г",
              "text": "Ісмаїл Гаспринський."
            }
          ],
          "correctKey": "Б",
          "answerText": "Ім’я автора надруковане перед циклом, а зовнішня біографія пояснює зв’язок його творчості з воєнним досвідом.",
          "optionSource": "prepared-v21-test",
